s=json.loads(Path(os.environ['ORBIT_QA_STATE_FILE']).read_text());base=os.environ['ORBIT_E2E_BASE_URL'];path=os.environ['ORBIT_QA_DB_PATH'];media=Path(os.environ['ORBIT_QA_MEDIA_DIR']);assert path.startswith('/tmp/') and str(media).startswith('/tmp/') and base.startswith('http://127.0.0.1:');project=s['project'];prefix='批量审核'+str(time.time_ns());db=sqlite3.connect(path)
role=db.execute('SELECT role_id FROM users WHERE id=?',(s['worker'],)).fetchone()[0];reviewer=db.execute("INSERT INTO users(username,display_name,password_hash,role_id,must_change_password) VALUES(?,?,'x',?,0) RETURNING id",(prefix,'仅审核测试账号',role)).fetchone()[0];db.execute('INSERT INTO project_visibility(project_id,user_id,granted_by) VALUES(?,?,?)',(project,reviewer,s['admin']));db.execute('INSERT INTO project_leaders(project_id,user_id) VALUES(?,?)',(project,reviewer));db.execute('INSERT INTO project_user_permissions(project_id,user_id,permissions_json,updated_by,scope_version) VALUES(?,?,?,?,2)',(project,reviewer,json.dumps(['cross.view','cross.review']),s['admin']));token=secrets.token_hex(24);db.execute('INSERT INTO user_sessions(user_id,token_hash,expires_at) VALUES(?,?,?)',(reviewer,hashlib.sha256(token.encode()).hexdigest(),(datetime.datetime.now(datetime.timezone.utc)+datetime.timedelta(days=1)).isoformat()));cookie='orbit_session='+token
category=db.execute('SELECT product_category_id FROM cross_records WHERE id=?',(s['mother'],)).fetchone()[0]
def png():
 def ck(k,b):return struct.pack('>I',len(b))+k+b+struct.pack('>I',zlib.crc32(k+b)&0xffffffff)
 return b'\x89PNG\r\n\x1a\n'+ck(b'IHDR',struct.pack('>IIBBBBB',40,40,8,2,0,0,0))+ck(b'IDAT',zlib.compress((b'\0'+b'\xa3\xbe\xdd'*40)*40))+ck(b'IEND',b'')
def row(kind,title,doc=False):
 id=db.execute("INSERT INTO cross_records(project_id,kind,parent_id,main_id,title,creator_id,maker_id,package_type,product_category_id,body_json,source_locked) VALUES(?,?,?,?,?,?,?,?,?,'{}',1) RETURNING id",(project,kind,s['mother'] if doc else None,s['main'] if doc else None,title,s['worker'],s['worker'],'document' if doc else 'main',category)).fetchone()[0]
 if doc:db.execute("INSERT INTO cross_tasks(project_id,stage,source_id,result_id,package_type,assignee_id,status,manual_owner,task_key) VALUES(?,'child',?,?,'document',?,'making',1,?)",(project,s['main'],id,s['worker'],prefix+'-'+str(id)))
 for i in range(1 if doc else 2):
  data=b'%PDF-1.4\n%%EOF' if doc else png();name=('文档.pdf' if doc else '图片'+str(i+1)+'.png');key='review-queue/'+str(id)+'/'+name;file=media/key;file.parent.mkdir(parents=True,exist_ok=True);file.write_bytes(data);db.execute("INSERT INTO cross_files(record_id,storage_path,file_name,mime_type,file_size,uploader_id,position) VALUES(?,?,?,?,?,?,?)",(id,key,name,'application/pdf' if doc else 'image/png',len(data),s['worker'],i))
 return id
mothers=[row('mother',prefix+'母版甲'),row('mother',prefix+'母版乙')];docs=[row('package',prefix+'文档甲',True),row('package',prefix+'文档乙',True),row('package',prefix+'文档丙',True)];db.commit();checks=0;errors=[];out=Path('/tmp/v333-review-screenshots');out.mkdir(exist_ok=True)
with sync_playwright() as p:
 api=p.request.new_context(extra_http_headers={'cookie':s['cookies']['worker'],'x-orbit-project-id':str(project)})
 def detail(id):
  r=api.get(base+'/api/cross-records?id='+str(id));assert r.status==200,r.text();return r.json()
 def change(id,action,extra=None):
  d=detail(id);r=api.patch(base+'/api/cross-records/'+str(id),data={'action':action,'revision':d['row']['revision'],**(extra or {})});assert r.status==200,(r.status,r.text());return r.json()
 for id in mothers+docs:change(id,'submit')
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);c=browser.new_context(viewport={'width':1450,'height':950});n,v=cookie.split('=',1);c.add_cookies([{'name':n,'value':v,'url':base}]);page=c.new_page();page.set_default_timeout(10000);page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base,wait_until='networkidle');page.locator('#project-tab-'+str(project)).click();page.get_by_role('dialog').get_by_role('button',name='确认继续').click();nav=page.get_by_role('navigation',name='项目二级导航');nav.get_by_role('button',name='母版库').click()
 for id in mothers:page.locator('tr[data-record-id="'+str(id)+'"]').get_by_role('checkbox').check()
 page.get_by_role('button',name='审核所选（2）',exact=True).click();page.get_by_role('dialog',name='操作确认',exact=True).get_by_role('button',name='确认继续',exact=True).click();q=page.get_by_role('dialog',name='批量审核',exact=True);expect(q).to_be_visible();expect(q.get_by_role('button',name='上一个',exact=True)).to_be_disabled();expect(q.get_by_role('button',name='下一个',exact=True)).to_be_enabled();expect(q.locator('.cross-review-previews button')).to_have_count(2);checks+=4
 first=int(q.locator('.review-queue-subject h3').inner_text().endswith('甲'));order=list(reversed(mothers));assert q.locator('.review-queue-subject h3').inner_text().endswith('乙');checks+=1
 q.get_by_role('button',name='审核通过',exact=True).click();expect(q).to_contain_text('本条已审核通过');expect(q.get_by_role('button',name='审核通过',exact=True)).to_be_disabled();assert detail(order[0])['row']['status']=='approved';checks+=3
 q.get_by_role('button',name='下一个',exact=True).click();expect(q.locator('.review-queue-subject h3')).to_contain_text('甲');expect(q.get_by_role('button',name='下一个',exact=True)).to_be_disabled();q.get_by_role('button',name='退回修改',exact=True).click();expect(q.get_by_role('alert')).to_contain_text('请填写');expect(q.get_by_role('textbox',name='退回原因')).to_be_focused();checks+=4
 q.get_by_role('textbox',name='退回原因').fill('第二张图片需要修改');q.get_by_role('button',name='上一个',exact=True).click();confirm=page.get_by_role('dialog',name='操作确认',exact=True);expect(confirm).to_be_visible();confirm.get_by_role('button',name='取消',exact=True).click();expect(q.get_by_role('textbox',name='退回原因')).to_have_value('第二张图片需要修改');checks+=2
 q.get_by_role('button',name='退回修改',exact=True).click();expect(q).to_contain_text('本条已退回修改');assert detail(order[1])['row']['status']=='rejected';q.get_by_role('button',name='上一个',exact=True).click();expect(q.get_by_role('button',name='审核通过',exact=True)).to_be_disabled();q.get_by_role('button',name='退出',exact=True).click();expect(q).to_have_count(0);checks+=3
 # Product pending list includes child packages, reviewed through the same queue.
 nav.get_by_role('button',name='产品管理').click();page.get_by_role('tab',name='待审核',exact=True).click()
 for id in docs:page.locator('tr[data-record-id="'+str(id)+'"]').get_by_role('checkbox').check()
 page.get_by_role('button',name='审核所选（3）',exact=True).click();page.get_by_role('dialog',name='操作确认',exact=True).get_by_role('button',name='确认继续',exact=True).click();expect(q).to_be_visible();expect(q.locator('.cross-review-documents button')).to_have_count(1);page.screenshot(path=str(out/'review-queue.png'));q.locator('.cross-review-documents button').click();expect(page.get_by_role('dialog')).to_have_count(2);page.get_by_role('dialog').last.get_by_role('button',name='关闭弹窗',exact=True).click();expect(q).to_be_visible();checks+=4
 # An external reviewer completes this record after it was loaded; stale approval must not duplicate.
 admin=p.request.new_context(extra_http_headers={'cookie':s['cookies']['admin'],'x-orbit-project-id':str(project)});current=docs[-1];d=detail(current);r=admin.patch(base+'/api/cross-records/'+str(current),data={'action':'approve','revision':d['row']['revision']});assert r.status==200;r=admin.get(base+'/api/cross-records?id='+str(current));q.get_by_role('button',name='审核通过',exact=True).click();expect(q.get_by_role('alert')).to_contain_text('更新');expect(q.get_by_role('button',name='审核通过',exact=True)).to_be_disabled();assert db.execute("SELECT count(*) FROM cross_events WHERE record_id=? AND action='approve'",(current,)).fetchone()[0]==1;checks+=3
 q.get_by_role('button',name='下一个',exact=True).click();expect(q.get_by_role('button',name='审核通过',exact=True)).to_be_enabled();q.get_by_role('button',name='审核通过',exact=True).click();expect(q).to_contain_text('本条已审核通过');assert detail(docs[-2])['row']['status']=='approved';checks+=2
 q.get_by_role('button',name='下一个',exact=True).click();expect(q.get_by_role('button',name='下一个',exact=True)).to_be_disabled();page.set_viewport_size({'width':390,'height':844});expect(q.get_by_role('button',name='退出',exact=True)).to_be_visible();assert q.get_by_role('button',name='下一个',exact=True).bounding_box()['y']<844;checks+=2;q.get_by_role('button',name='退出',exact=True).click();assert detail(docs[0])['row']['status']=='pending';checks+=1
 assert not errors,errors;browser.close();print(json.dumps({'checks':checks,'pageErrors':errors,'screenshots':str(out)},ensure_ascii=False));db.close()
